  for (int i = 0; i < musicString.length / 2; i++) {
    if (musicString[i] == 'o') {
      int duration = 4; // whole note
      while (i + 1 < musicString.length && musicString[i + 1] == '|') {
        i++;
        duration -= 2;
      }
      notes.add(duration);
    } else if (musicString[i] == '.') {
      int duration = 1; // quarter note
      while (i + 1 < musicString.length && musicString[i + 1] == '|') {
        i++;
        duration += 1;
      }
      notes.add(duration);
    }
  }
  return notes;
}

