List<int> parseMusic(String musicString) {
  List<int> beats = [];

  for (int i = 0; i < musicString.length; i++) {
    String currentBeat = "";

    // Collect consecutive characters until a separator is found.
    while (i < musicString.length && 
           musicString[i] != ' ') {
      currentBeat += musicString[i];
      i++;
    }

    if (currentBeat.isNotEmpty) {
      int beatValue = -1;

      switch (currentBeat) {
        case "o":   // Whole note: count as 4
          beatValue = 4;
          break;
        case ".|": // Half note: count as 2
          beatValue = 2;
          break;
        default:   // Quarter or eighths ("." or "|") are counted as 1 each
          beatValue = 1;
      }

      beats.add(beatValue);
    } else {
      i--; // Step back because the outer loop will increment again
    }
  }

  return beats;
}

