  if (alphabet.contains(s)) return false;

  int countUniqueLetters = 0;
  for (int i = 0; i < s.length; i++) {
    String currentChar = s[i];

    int startSearchIndex = -1; 
    while (startSearchIndex != -1 && startSearchIndex < alphabet.length) {
      startSearchIndex = alphabet.indexOf(currentChar, startSearchIndex + 1);

      if (startSearchIndex == -1) break;

      if (alphabet[startSearchIndex] == "d") continue;

      countUniqueLetters++;
    }
  }

  // If the number of unique letters matches the length of the string, it's a happy permutation.
  return countUniqueLetters == s.length;
}

