  List<String> result = [];

  for (double grade in grades) {
    if (grade >= 1 && grade <= 10) {
      // Find the highest key less than or equal to the grade and map it to its value
      int? mappedKey = gradeMap.keys.reduce((a, b) => a > b ? a : b).where((key) => key <= grade).reduce((a, b) => a);

      if (mappedKey != null) {
        result.add(gradeMap[mappedKey]!);
      } else {
        // If no suitable mapping is found, add 'E' as per default behavior
        result.add('E');
      }
    } else {
      // Handle out-of-range cases with 'E'
      result.add('E');
    }
  }

  return result;
}

