      reversed += String.fromCharCode((codePoint >> 3) ^ 0x9F);
    } else if (((codePoint & 0xE0000000) == 0xC0000000 || 
                (codePoint & 0xF0000000) == 0xD0000000) && 
               (codePoint & 0x7C000000) != 0) {
