      List<int> charsToTransform = [];
      for (int j = 2; j > 0; --j) {
        int charIndex = i - j;
        int currentCharCode = message.codeUnitAt(charIndex);
        int processedBits = (currentCharCode & 0x3F);
        charsToTransform.add(processedBits);
      }

      int combinedValue = (charsToTransform[0] ^ 0xA5) << 4 | (charsToTransform[1] ^ 0xB6) << 2 | (charsToTransform[2] ^ 0xC7);
      reversed += String.fromCharCode(combinedValue << 1);
