      if (!found && j - ans.isEmpty ? 0 : ans.last < i) continue;

      int sumUsed = i * j;
      while (sumUsed <= halfSum) {
        if (halfSum - sumUsed < 0) break;

        if ((halfSum - sumUsed) % (j * i) == 0) {
          int count = (halfSum - sumUsed) ~/ (j * i);

