class Solution {
  int minSubArraySum(List<int> nums) {
    List<int> n = [];

    for (int i = 0; i < nums.length - 1; i++) {
      if ((nums[i] + nums[i + 1]) % 2 == 0 && 
          !n.contains(nums[i]) && 
          !n.contains(nums[i + 1])) {
        n.add(nums[i]);
        n.add(nums[i + 1]);
      } else if (i >= nums.length - 2) {
        n.add(nums[nums.length - 1]);
      }
    }

    if (n.isEmpty || n.length > nums.length / 2) return 0;

    // Count occurrences of each number in the result list
    Map<int, int> counts = {};
    for (var num in n) {
      counts.putIfAbsent(num, () => 0);
      counts[num]++;
    }

    // Find maximum frequency and corresponding value
    var maxCount = 0;
    var maxValue = 0;

    for (var entry in counts.entries) {
      if (entry.value > maxCount) {
        maxCount = entry.value;
        maxValue = entry.key;
      }
    }

    if (maxCount * 2 <= n.length) {
      return maxValue * maxCount;
    }

    return 0;
  }
}

