  bool _canFill(int row, int col, List<List<bool>> visited) {
    int rows = grid.length;
    int cols = grid[0].length;

    // If the current position is out of bounds or already filled, return false.
    if (row < 0 || row >= rows || col < 0 || col >= cols || grid[row][col] != 1 || visited[row][col]) {
      return false;
    }

    // Mark the current cell as visited and fill it with water.
    visited[row][col] = true;
    grid[row][col] = 2;

    // Recursively explore neighboring cells.
    _canFill(row + 1, col, visited);
    _canFill(row - 1, col, visited);
    _canFill(row, col + 1, visited);
    _canFill(row, col - 1, visited);

    return true;
  }

