            if (!visited[r][c] && grid[r][c] == 1) {
              visited[r][c] = true;
              grid[r][c] = 2;
              componentSize++;
              if (componentSize > capacity) break;
              stack.add((r + 1, c));
              stack.add((r - 1, c));
              stack.add((r, c + 1));
              stack.add((r, c - 1));
            }
          }
        }
      }
