List<Position> _flood(List<List<int>> grid, Position start) {
  final queue = [start];
  final visited = Set.from([start]);

  while (queue.isNotEmpty) {
    final current = queue.removeAt(0);

    for (dx = -1; dx <= 1; ++dx) {
      for (dy = -1; dy <= 1; ++dy) {
        if ((dx == 0 && dy == 0)) continue;

        final nx = current.x + dx;
        final ny = current.y + dy;

        if (nx >= 0 && 
            ny >= 0 && 
            nx < grid[ny].length && 
            ny < grid.length && 
            !visited.contains(Position(nx, ny)) && 
            grid[ny][nx] == 1) {
          visited.add(Position(nx, ny));
          queue.add(Position(nx, ny));
        }
      }
    }
  }

  return visited.toList();
}

int maxFill(List<List<int>> grid, int capacity) {
  Set<Iterable<int>> visited = {};

  void dfs(Iterable<int> coordinates) {
    if (visited.contains(coordinates)) return;
    if (coordinates.length > capacity || !grid[coordinates.first][coordinates.last]) return;
    for (var i = -1; i <= 1; ++i) {
      for (var j = -1; j <= 1; ++j) {
        var newCoordinates = [coordinates.first + i, coordinates.last + j];
        if (!newCoordinates.every((n) => n >= 0 && n < grid.length) || grid[newCoordinates.first][newCoordinates.last] == 1) continue;
        visited.add(newCoordinates);
        grid[newCoordinates.first][newCoordinates.last] = 1;
        dfs(newCoordinates);
      }
    }
  }

  Iterable<int> allCells() sync* {
    for (var y = 0; y < grid.length; ++y) {
      for (var x = 0; x < grid[y].length; ++x) yield [y, x];
    }
  }

  var totalCapacity = 0;
  for (var cell in allCells()) {
    if (!grid[cell.first][cell.last]) {
      visited.clear();
      visited.add(cell);
      grid[cell.first][cell.last] = 1;
      dfs(cell);
      totalCapacity += visited.length;
    }
  }

  return totalCapacity;
}

